/* SideNav — a routing-agnostic vertical navigation rail. Reusable extraction of
 * shell/Sidebar: same visual language (pill rail, collapsed icon circle) but
 * driven by props, self-managing its collapsed state via [data-collapsed]. */

.side-nav {
  display: grid;
  grid-template-rows: auto 1fr auto; /* logo / rail / footer */
  /* The one column is CAPPED, not implicit.
   *
   * Without this the implicit column is `auto`, which cannot get smaller than the
   * min-content of its items — and an item's label is `white-space: nowrap`, so its
   * min-content IS the whole name. A long team name ("Global Design System Factory")
   * therefore blew the rail past its own `inline-size`, ate the inline padding, and
   * ran over the page beside it, while `text-overflow: ellipsis` never fired because
   * nothing ever constrained the label. `minmax(0, 1fr)` lets the column shrink, so
   * the label truncates instead of the rail growing. */
  grid-template-columns: minmax(0, 1fr);

  /* Stays put while the page scrolls, BY DEFAULT.
   *
   * This used to say "make the container 100dvh / sticky for an app sidebar",
   * leaving it to the consumer. Not one consumer did it: one app got it by accident
   * through <AppLayout>, whose nav column is sticky, and another hand-rolled its
   * own shell grid and so scrolled the whole navigation off the top of the screen.
   * A component whose job IS to be an app's navigation should not need a note
   * telling every app to remember two lines. Embedding it inside a shorter box
   * still works: `position: sticky` degrades to static flow when there is nothing
   * to scroll, and a consumer that wants a plain block can override these three
   * declarations from its own stylesheet. */
  position: sticky;
  inset-block-start: 0;
  block-size: 100dvh;

  min-block-size: 0;
  inline-size: var(--sidebar-width);
  padding: var(--space-4) var(--space-3);
  background: transparent;
  overflow: visible;
}

/* Same inline padding as .side-nav-item, so the brand sits on the nav's grid
 * instead of floating off on its own. */
.side-nav-header { display: flex; align-items: center; padding: 0 var(--space-3) var(--space-6); }
.side-nav-logo {
  display: inline-flex; align-items: center; gap: var(--space-2);
  border: 0; background: transparent; padding: 0; font: inherit; color: var(--foreground);
  text-decoration: none; border-radius: var(--radius-sm);
}
button.side-nav-logo { cursor: pointer; }
/* A BRAND THAT LINKS HOME IS STILL THE BRAND. When `collapseControl` moves the
 * toggle off the mark, the slot is a plain span, and whatever a product puts
 * inside it keeps its own styles: an <a href> home came out underlined and
 * link-blue with the wordmark stacked under the icon, because the anchor is
 * inline and the slot's rules stop at the slot (2026-08-29). The brand's box
 * and its ink belong to anything standing in for the brand. */
.side-nav-logo a {
  display: inline-flex; align-items: center; gap: var(--space-2);
  color: inherit; text-decoration: none;
}
.side-nav-logo:focus-visible { outline: var(--focus-ring); outline-offset: calc(var(--ring-offset) * 2); }

/* The rail (menu + anything under it) sits in the MIDDLE of the row between the
 * logo and the footer, open and collapsed alike. Content-sized, so it does not
 * jump when a page has a longer or shorter menu, and the collapsed pill hangs
 * centred rather than clinging to the brand. */
/* At the TOP while the rail carries words, centred once it is icons only.
 *
 * Centred always, the navigation floated in the middle of a tall panel with a
 * band of nothing above it — the shape the page audit calls a dead band. The
 * rule is not new: it was learned on the showcase's own rail and written down
 * there as `align: start | center`, and never made it into the system component
 * that replaced it (2026-08-24). */
.side-nav-rail { display: flex; flex-direction: column; min-block-size: 0; gap: var(--space-2); align-self: start; }
.side-nav[data-collapsed] .side-nav-rail { align-self: center; }
.side-nav-menu { display: flex; flex-direction: column; gap: var(--space-2); overflow-y: auto; flex: 0 0 auto; }
.side-nav-group { display: flex; flex-direction: column; gap: var(--space-1); }
.side-nav-group-label {
  padding: 0 var(--space-3); margin-block-start: var(--space-2);
  font-size: var(--font-xs); font-weight: var(--font-weight-semibold);
  text-transform: uppercase; letter-spacing: var(--tracking-wide); color: var(--muted-foreground);
}

.side-nav-item {
  display: flex; align-items: center; gap: var(--space-2);
  min-block-size: var(--control-height); padding: var(--space-2) var(--space-3);
  border: 0; background: transparent; font: inherit; inline-size: 100%; text-align: start; cursor: pointer;
  border-radius: var(--radius-full); color: var(--muted-foreground); text-decoration: none;
  white-space: nowrap; min-inline-size: 0;
  transition: background var(--duration-fast), color var(--duration-fast);
}
.side-nav-item-text { display: flex; flex-direction: column; min-inline-size: 0; line-height: var(--leading-tight); }
.side-nav-item-label { min-inline-size: 0; overflow: hidden; text-overflow: ellipsis; }
.side-nav-item-sub { font-size: var(--font-xs); color: var(--muted-foreground); overflow: hidden; text-overflow: ellipsis; }
/* The icon and the trailing badge keep their size; the label is what gives way. */
.side-nav-item > .icon { flex: 0 0 auto; }
.side-nav-item-trailing { margin-inline-start: auto; display: inline-flex; flex: 0 0 auto; padding-inline-start: var(--space-2); }

.side-nav-item:hover { background: var(--accent); color: var(--foreground); }
/* Pressed: one stop past hover, the third answer every control now gives. */
.side-nav-item:active { background: var(--accent-strong); }
.side-nav-item:focus-visible { outline: var(--focus-ring); outline-offset: var(--focus-ring-inset); }
/* ONE ANSWER FOR "YOU ARE HERE", IN BOTH STATES — and it is not a grey.
 * Collapsed, the current item used to be a solid --primary disc. The brand mark
 * above it is a solid brand disc too in every product that caps its logo, so
 * the collapsed rail showed two identical circles and the top one read as a
 * second menu entry — the owner's finding on this site's own rail
 * (2026-08-24, and the two glyphs were near enough to settle it).
 *
 * What replaced it was --accent, the fill hover already uses, which made the
 * current place indistinguishable from a hovered one; collapsed to a 40px disc
 * on a card, one neutral step over the surface it sits on is not a signal at
 * all (owner, 30.08: the active item does not register).
 *
 * THE ANSWER IS THE INK, AND ONLY THE INK. A tinted disc with a brand hairline
 * was tried the same afternoon and read loudly — too loudly: it put a second
 * coloured circle under a brand mark that is already one, and the rail became
 * two competing discs (owner, same day: I would drop the shadow and make it just
 * the active icon). What made the ink enough is that the ink is now correct: on
 * this brand it had been resolving to the stop chosen for a WHITE page, 2.27:1
 * on the dark rail, which is why nothing registered. At 5.8:1 a single glyph in
 * the brand's colour, on a rail where every other glyph is grey, is the loudest
 * thing there without a shape around it. Hover keeps the neutral fill, so the
 * two states still differ: one is a ground, the other is a colour. */
.side-nav-item.is-active {
  color: var(--nav-active-foreground);
  background: transparent;
}
.side-nav-item.is-active .side-nav-item-label { font-weight: var(--font-weight-semibold); }
/* Hover still answers, and it answers the way every other row does. */
.side-nav-item.is-active:hover { background: var(--accent); color: var(--nav-active-foreground); }

.side-nav-toggle { border: 1px solid var(--border-strong); }

.side-nav-footer { display: flex; flex-direction: column; gap: var(--space-1); padding-block-start: var(--space-2); }

/* ── Collapsed (icon rail) ─────────────────────────────────────── */
.side-nav[data-collapsed] { inline-size: auto; padding-inline: var(--space-4) 0; }
.side-nav[data-collapsed] .side-nav-rail {
  align-items: center; gap: var(--space-3);
  /* Hug the icon column. Without this the pill stretched to whatever width the
   * container offered, and the rail became a wide white capsule with a thin
   * line of icons in the middle whenever it was not inside a fixed nav column. */
  inline-size: fit-content;
  margin-inline: auto;
  padding: var(--space-4) var(--space-2);
  /* No lift. The pill is a QUIET ground the icons stand on, not a floating sheet:
   * a shadow under a shape that never moves and never overlaps anything is
   * decoration, and on a dark canvas it only muddies the edge (owner, 30.08). */
  background: var(--card); border-radius: var(--radius-full);
}
/* Collapsed: the mark alone, in a box the size of a rail item, so it lines up
 * with the icons below it. The DS paints NO cap here — a brand mark that turns
 * into white-on-teal the moment the rail collapses is a product decision, and
 * the component would impose it on any logo passed in (a wordmark came out as
 * white text in a teal circle). A product that wants a cap ships it inside its
 * own `logoMark`. */
.side-nav[data-collapsed] .side-nav-header {
  justify-content: center; inline-size: var(--sidebar-rail-item-size); aspect-ratio: 1;
  padding: 0; margin: 0 auto var(--space-2); overflow: hidden;
}
/* Unless the product shipped a mark for this state. The clip above exists to
 * stop a WORDMARK spilling out of a 40px box when no `logoMark` was given; a
 * mark that was made for the rail is exactly 40px, and clipping shaved its
 * edge — a circle with its sides cut off (owner, 2026-08-24). */
.side-nav[data-collapsed][data-has-mark] .side-nav-header { overflow: visible; }
.side-nav[data-collapsed] .side-nav-logo { inline-size: 100%; block-size: 100%; justify-content: center; }
.side-nav[data-collapsed] .side-nav-group { align-items: center; gap: var(--space-3); }
/* Expanded, the uppercase heading is what says where a group ends, so the rule would be a second
   answer to the same question. Collapsed, the heading is gone and the rule is the only one left —
   it spans the icon column, not the pill, so it lines up with what it separates. */
.side-nav-separator { display: none; }
.side-nav[data-collapsed] .side-nav-separator { display: block; inline-size: var(--sidebar-rail-item-size); }
.side-nav[data-collapsed] .side-nav-group-label { display: none; }
.side-nav[data-collapsed] .side-nav-menu { align-items: center; gap: var(--space-3); }
.side-nav[data-collapsed] .side-nav-item {
  inline-size: var(--sidebar-rail-item-size); block-size: var(--sidebar-rail-item-size);
  min-block-size: 0; padding: 0; justify-content: center; border-radius: var(--radius-full);
}
.side-nav[data-collapsed] .side-nav-item-text,
.side-nav[data-collapsed] .side-nav-item-trailing { display: none; }
.side-nav[data-collapsed] .side-nav-footer { align-items: center; }

/* Mobile: always the full column, no pill. */
@media (max-width: 48rem) {
  .side-nav, .side-nav[data-collapsed] { inline-size: 100%; padding-inline: var(--space-3); }
  .side-nav[data-collapsed] .side-nav-rail { align-self: stretch; gap: var(--space-2); padding: 0; background: transparent; box-shadow: none; align-items: stretch; }
  .side-nav[data-collapsed] .side-nav-header { inline-size: auto; aspect-ratio: auto; margin: 0; padding: 0 var(--space-3) var(--space-6); justify-content: flex-start; }
  .side-nav[data-collapsed] .side-nav-menu { align-items: stretch; gap: var(--space-2); }
  .side-nav[data-collapsed] .side-nav-item { inline-size: 100%; block-size: auto; min-block-size: var(--control-height); padding: var(--space-2) var(--space-3); justify-content: flex-start; }
  .side-nav[data-collapsed] .side-nav-item-text { display: flex; }
  .side-nav[data-collapsed] .side-nav-group-label { display: block; }
  /* The labels are back, so the rule is redundant again. */
  .side-nav[data-collapsed] .side-nav-separator { display: none; }
}

import "./SideNav.css";
import { Fragment, useState, type ReactElement, type ReactNode } from "react";
import { cn } from "../lib/cn";
import { Divider } from "../Divider";
import { Icon, type IconName } from "../Icon";
import { Tooltip } from "../Tooltip";

/** One navigable entry. Routing-agnostic three ways, and the third is the one a
 *  router app wants: pass `href` for a plain anchor, `onSelect` for a button, or
 *  `render` to wrap the entry's own markup in your router's link.
 *
 *  `render` exists because the other two both cost something in a single-page
 *  app, and until 2026-08-23 every product paid the second price without
 *  choosing it: `href` reloads the whole document, so all three apps used
 *  `onSelect`, and every navigation entry in every product became a <button>.
 *  A button cannot be middle-clicked into a new tab, cannot have its address
 *  copied, and is announced as a button to someone who is navigating. */
export type SideNavItem = {
  id: string;
  label: string;
  icon?: IconName;
  /** Secondary line under the label (hidden when collapsed). */
  sublabel?: string;
  /** Right-aligned slot, e.g. a <Badge> (hidden when collapsed). */
  trailing?: ReactNode;
  /** What to call this entry in a product's own usage log, when the label is not the
   *  answer. A rail entry that carries a `trailing` number reads as one control today
   *  and another tomorrow, because the number moves with it. */
  usage?: string;
  active?: boolean;
  href?: string;
  onSelect?: () => void;
  /**
   * Wrap the entry in your own link. The callback is handed the entry's inner
   * markup and the class and ARIA it must carry; return an element that renders
   * them. `href` and `onSelect` are ignored when it is given, because the link
   * you return owns the navigation.
   */
  render?: (inner: ReactNode, props: { className: string; 'aria-current'?: 'page'; 'data-usage'?: string }) => ReactElement;
};

export type SideNavGroup = {
  /** Optional uppercase group heading (hidden when collapsed). */
  label?: string;
  items: SideNavItem[];
};

/** How the collapse control is exposed: a row at the `bottom` of the rail, by
 *  clicking the `logo`, or `both`. */
type CollapseControl = "bottom" | "logo" | "both";

type Props = {
  groups: SideNavGroup[];
  /** Full brand lockup, shown when expanded (mark + wordmark). */
  logo?: ReactNode;
  /** The mark alone, shown when collapsed. Provide it whenever the rail can
   *  collapse: the fallback is `logo`, and a wordmark does not fit the rail. */
  logoMark?: ReactNode;
  /** Pinned to the bottom (e.g. a user menu). */
  footer?: ReactNode;
  /** Master switch for the collapse affordance (default true). */
  collapsible?: boolean;
  /**
   * Which control collapses the rail. `logo` is the default and is the decided
   * answer: collapsed, the biggest target on the rail is what opens the rail,
   * and expanded, hovering the mark says what pressing it will do. It used to
   * default to `bottom`, and the measurement on 2026-08-23 was that no product
   * passed this prop at all — so every one of them carried a Collapse button
   * nobody had chosen, while the behaviour they wanted sat behind a default.
   */
  collapseControl?: CollapseControl;
  /** Controlled collapsed state. Omit to let the component manage it. */
  collapsed?: boolean;
  /** The state on first render when the rail owns its own; ignored once `collapsed` is passed.
   *  Start collapsed only where the product is a workspace people live in rather than navigate.
   */
  defaultCollapsed?: boolean;
  /** Called with the next collapsed state, for a product that persists the rail across sessions.
   *  Omit it and the rail keeps its own state.
   */
  onCollapsedChange?: (collapsed: boolean) => void;
  "aria-label"?: string;
};

/**
 * The application navigation column: sections, the active route, and the
 * collapse to an icon rail.
 */
export function SideNav({
  groups,
  logo,
  logoMark,
  footer,
  collapsible = true,
  collapseControl = "logo",
  collapsed,
  defaultCollapsed = false,
  onCollapsedChange,
  "aria-label": ariaLabel = "Primary",
}: Props) {
  const [internal, setInternal] = useState(defaultCollapsed);
  const isCollapsed = collapsible && (collapsed ?? internal);
  /* The logo can only be the control if there IS one. Without this a rail with
   * no logo and the default control would have no way to collapse at all —
   * found by the existing tests the moment the default changed, which is what
   * they are for. */
  const logoTogglable = collapsible && !!(logo ?? logoMark) && (collapseControl === "logo" || collapseControl === "both");
  const showBottomToggle = collapsible && (collapseControl === "bottom" || collapseControl === "both" || !logoTogglable);

  function toggle() {
    const next = !isCollapsed;
    onCollapsedChange?.(next);
    if (collapsed === undefined) setInternal(next);
  }

  const brand = isCollapsed ? (logoMark ?? logo) : logo;

  return (
    /* THE NAVIGATION IS THE LANDMARK, and the rail around it is chrome.
       This was an <aside aria-label> wrapping an unnamed <nav>, which is two
       landmarks for one thing and only one of them named: axe reported
       `landmark-unique` the moment a second rail appeared on the page, and the
       same fires on any page carrying a breadcrumb or a footer nav beside this
       one (2026-08-29). The name belongs on the element it names. */
    <div className="side-nav" data-collapsed={isCollapsed || undefined} data-has-mark={logoMark ? "" : undefined}>
      {brand && (
        <div className="side-nav-header">
          {logoTogglable ? (
            <button
              type="button"
              className="side-nav-logo"
              onClick={toggle}
              aria-label={isCollapsed ? "Expand navigation" : "Collapse navigation"}
              aria-expanded={!isCollapsed}
            >
              {brand}
            </button>
          ) : (
            <span className="side-nav-logo">{brand}</span>
          )}
        </div>
      )}

      <div className="side-nav-rail">
        <nav className="side-nav-menu" aria-label={ariaLabel}>
          {groups.map((group, gi) => (
            // eslint-disable-next-line @eslint-react/no-array-index-key -- the label IS the key; the index only covers an unlabelled group, of which there is at most one
            <Fragment key={group.label ?? gi}>
              {/* Collapsed, the group heading is gone and the icons of three groups run together
                  as one column, so the rule takes the heading's place as the thing that says
                  where a group ends. Rendered always, shown by CSS only where it is needed:
                  expanded (and on mobile, which stays expanded) the heading already does the job. */}
              {gi > 0 && <Divider className="side-nav-separator" />}
              <div className="side-nav-group">
                {group.label && <div className="side-nav-group-label">{group.label}</div>}
                {group.items.map((item) => {
                  const inner = (
                    <>
                      {item.icon && <Icon name={item.icon} size="md" />}
                      <span className="side-nav-item-text">
                        {/* A name too long for the rail truncates, so the full one stays
                            reachable on hover rather than being lost to the ellipsis. */}
                        <span className="side-nav-item-label" title={item.label}>{item.label}</span>
                        {item.sublabel && <span className="side-nav-item-sub">{item.sublabel}</span>}
                      </span>
                      {item.trailing && <span className="side-nav-item-trailing">{item.trailing}</span>}
                    </>
                  );
                  const className = cn("side-nav-item", item.active && "is-active");
                  const shared = {
                    className,
                    "aria-current": item.active ? ("page" as const) : undefined,
                    "data-usage": item.usage,
                  };
                  const node = item.render ? (
                    item.render(inner, shared)
                  ) : item.href ? (
                    <a href={item.href} className={className} onClick={item.onSelect}
                      data-usage={item.usage} aria-current={item.active ? "page" : undefined}>
                      {inner}
                    </a>
                  ) : (
                    <button type="button" className={className} onClick={item.onSelect}
                      data-usage={item.usage} aria-current={item.active ? "page" : undefined}>
                      {inner}
                    </button>
                  );
                  return (
                    <Tooltip key={item.id} content={item.label} placement="end" enabled={isCollapsed}>
                      {node}
                    </Tooltip>
                  );
                })}
              </div>
            </Fragment>
          ))}

          {showBottomToggle && (
            <Tooltip content={isCollapsed ? "Expand" : "Collapse"} placement="end" enabled={isCollapsed}>
              <button type="button" className="side-nav-item side-nav-toggle" onClick={toggle}
                aria-label={isCollapsed ? "Expand navigation" : "Collapse navigation"}
                aria-expanded={!isCollapsed}>
                <Icon name={isCollapsed ? "arrow_right_to_line" : "arrow_left_to_line"} size="md" />
                <span className="side-nav-item-text">
                  <span className="side-nav-item-label">{isCollapsed ? "Expand" : "Collapse"}</span>
                </span>
              </button>
            </Tooltip>
          )}
        </nav>
      </div>

      {footer && <div className="side-nav-footer">{footer}</div>}
    </div>
  );
}
